I'll show you the complete implementation. Here's a production-ready authentication system:

## **1. package.json**
```json
{
  "name": "auth-system",
  "version": "1.0.0",
  "type": "module",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "node --watch server.js"
  },
  "dependencies": {
    "express": "^4.18.2",
    "bcrypt": "^5.1.1",
    "jsonwebtoken": "^9.1.2",
    "sqlite3": "^5.1.6",
    "express-validator": "^7.0.0"
  }
}
```

## **2. server.js**
```javascript
import express from 'express';
import sqlite3 from 'sqlite3';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { body, validationResult } from 'express-validator';
import { fileURLToPath } from 'url';
import { dirname } from 'path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const app = express();
app.use(express.json());

const db = new sqlite3.Database(':memory:');
const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-in-production';

// Rate limit store: email → {attempts: number, resetTime: timestamp}
const rateLimitStore = new Map();
const RATE_LIMIT_ATTEMPTS = 5;
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes

// Initialize database
db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);
});

// Middleware to check rate limiting
const checkRateLimit = (req, res, next) => {
  const email = req.body.email?.toLowerCase().trim();
  if (!email) return next();

  const now = Date.now();
  const record = rateLimitStore.get(email);

  if (record && now < record.resetTime) {
    if (record.attempts >= RATE_LIMIT_ATTEMPTS) {
      return res.status(429).json({
        error: 'Too many login attempts. Try again later.',
        retryAfter: Math.ceil((record.resetTime - now) / 1000)
      });
    }
  }

  next();
};

// Helper to update rate limit
const updateRateLimit = (email) => {
  email = email.toLowerCase().trim();
  const now = Date.now();
  const record = rateLimitStore.get(email);

  if (record && now < record.resetTime) {
    record.attempts++;
  } else {
    rateLimitStore.set(email, { attempts: 1, resetTime: now + RATE_LIMIT_WINDOW });
  }
};

// Helper to clear rate limit
const clearRateLimit = (email) => {
  rateLimitStore.delete(email.toLowerCase().trim());
};

// Middleware to verify JWT token
const verifyToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token provided' });

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid or expired token' });
  }
};

// Signup endpoint
app.post(
  '/auth/signup',
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { email, password } = req.body;

    try {
      const passwordHash = await bcrypt.hash(password, 12);

      db.run(
        'INSERT INTO users (email, password_hash) VALUES (?, ?)',
        [email, passwordHash],
        function(err) {
          if (err) {
            if (err.message.includes('UNIQUE constraint failed')) {
              return res.status(409).json({ error: 'Email already registered' });
            }
            throw err;
          }

          const token = jwt.sign({ userId: this.lastID, email }, JWT_SECRET, { expiresIn: '24h' });
          res.status(201).json({
            message: 'Account created successfully',
            token,
            user: { id: this.lastID, email }
          });
        }
      );
    } catch (err) {
      console.error(err);
      res.status(500).json({ error: 'Server error' });
    }
  }
);

// Login endpoint
app.post(
  '/auth/login',
  checkRateLimit,
  body('email').isEmail().normalizeEmail(),
  body('password').notEmpty(),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { email, password } = req.body;

    try {
      db.get('SELECT * FROM users WHERE email = ?', [email], async (err, user) => {
        if (err) {
          console.error(err);
          return res.status(500).json({ error: 'Server error' });
        }

        if (!user) {
          updateRateLimit(email);
          return res.status(401).json({ error: 'Invalid email or password' });
        }

        const isPasswordValid = await bcrypt.compare(password, user.password_hash);

        if (!isPasswordValid) {
          updateRateLimit(email);
          return res.status(401).json({ error: 'Invalid email or password' });
        }

        clearRateLimit(email);
        const token = jwt.sign({ userId: user.id, email: user.email }, JWT_SECRET, {
          expiresIn: '24h'
        });

        res.json({
          message: 'Logged in successfully',
          token,
          user: { id: user.id, email: user.email }
        });
      });
    } catch (err) {
      console.error(err);
      res.status(500).json({ error: 'Server error' });
    }
  }
);

// Protected route example
app.get('/auth/me', verifyToken, (req, res) => {
  res.json({ user: req.user });
});

// Logout endpoint (client-side token deletion recommended)
app.post('/auth/logout', verifyToken, (req, res) => {
  res.json({ message: 'Logged out successfully' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
```

## **Key Features:**

### **1. Password Hashing**
- Uses **bcrypt** with salt rounds of 12 for secure password storage
- Passwords never stored in plain text

### **2. Session Management**
- JWT tokens with 24-hour expiration
- Token includes userId and email
- Verified on protected routes

### **3. Rate Limiting**
- Tracks failed login attempts per email
- Blocks after 5 failed attempts for 15 minutes
- Automatically clears on successful login

### **4. Input Validation**
- Email format validation
- Minimum password length (8 characters)
- Email normalization
- Duplicate email detection

### **5. Security Best Practices**
- Generic error messages ("Invalid email or password")
- No password in responses
- JWT verification middleware
- Protected routes require valid token

## **Testing with curl:**

```bash
# Signup
curl -X POST http://localhost:3000/auth/signup \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"securepass123"}'

# Login
curl -X POST http://localhost:3000/auth/login \
  -H "Content-Type: application/json" \
  -d '{"email":"user@example.com","password":"securepass123"}'

# Protected route
curl -X GET http://localhost:3000/auth/me \
  -H "Authorization: Bearer YOUR_TOKEN_HERE"
```

